private void copySafeNodes(Element source, Element dest) {
        NodeTraversor.traverse(new NodeVisitor() {
            public void head(Node source, int depth) {
                if (source instanceof Element) {
                    Element sourceEl = (Element) source;
                    if (whitelist.isSafeTag(sourceEl.tagName())) {
                        ElementMeta meta = createSafeElement(sourceEl);
                        Element destChild = meta.el;
                        dest.appendChild(destChild);

                        // copy safe attributes; all safe, or forced by tag rules
                        Attributes sourceAttrs = sourceEl.attributes();
                        for (Attribute sourceAttr : sourceAttrs) {
                            if (whitelist.isSafeAttribute(sourceEl.tagName(), sourceEl, sourceAttr)) {
                                destChild.attributes().put(sourceAttr);
                            }
                        }
                    } else if (source instanceof TextNode) {
                        TextNode sourceText = (TextNode) source;
                        TextNode destText = new TextNode(sourceText.getWholeText(), source.baseUri());
                        dest.appendChild(destText); // updated because not cloning attributes
                    } else if (source instanceof DataNode && whitelist.isSafeTag(source.parent().nodeName())) {
                        DataNode sourceData = (DataNode) source;
                        DataNode destData = new DataNode(sourceData.getWholeData(), sourceData.baseUri());
                        dest.appendChild(destData);
                    } // else: safe to ignore
                } else if (source instanceof Comment) {
                    Comment sourceComment = (Comment) source;
                    Comment destComment = new Comment(sourceComment.getData(), source.baseUri());
                    dest.appendChild(destComment);
                }
            }

            public void tail(Node node, int depth) {
                // void
            }
        }, source);
    }

